def close_case_job(db, job: dict) -> None:
    db.execute(
        "UPDATE cases SET status = 'closed' "
        "WHERE id = :case_id",
        job,
    )

@app.post("/cases/{case_id}/close")
def close_case(
    case_id: str,
    background: BackgroundTasks,
    cache: redis.Redis = Depends(get_redis),
) -> dict:
    close_in_db(case_id)
    cache.delete(case_key(case_id))
    cache.set(f"summary:{case_id}",
              build_summary(case_id))
    background.add_task(send_close_email, case_id)
    return {"closed": case_id}
